-- Reference only. Run migrate.php for installation and seed data.
-- Content and calendar share one revisioned JSON row locked using SELECT FOR UPDATE.
CREATE TABLE IF NOT EXISTS elephant_state(id INTEGER PRIMARY KEY,revision INTEGER NOT NULL,body LONGTEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS admin_users(email VARCHAR(254) PRIMARY KEY,password_hash VARCHAR(255) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS rate_limits(bucket_key VARCHAR(128) PRIMARY KEY,hits INTEGER NOT NULL,expires_at BIGINT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mail_outbox(id VARCHAR(32) PRIMARY KEY,deduplication_key VARCHAR(190) NOT NULL UNIQUE,recipient VARCHAR(254) NOT NULL,subject VARCHAR(255) NOT NULL,body LONGTEXT NOT NULL,status VARCHAR(20) NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,available_at BIGINT NOT NULL,claimed_at BIGINT NULL,sent_at VARCHAR(30) NULL,last_error TEXT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
